using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;

namespace ContainerOrchestrator.Auth
{
    public class FeatureFlags
    {
        public bool EnableRateLimiting { get; set; } = true;
        public bool EnableAccountLockout { get; set; } = true;
        public bool EnableProgressiveDelay { get; set; } = true;
        public int MaxFailedAttempts { get; set; } = 5;
        public int LockoutDurationSeconds { get; set; } = 300;
        public int RateLimitWindowSeconds { get; set; } = 60;
        public int MaxRequestsPerWindow { get; set; } = 10;
    }

    public class AuthAttemptRecord
    {
        public int FailedCount { get; set; }
        public DateTime LastAttempt { get; set; }
        public DateTime? LockedUntil { get; set; }
        public Queue<DateTime> RequestTimestamps { get; set; } = new Queue<DateTime>();
    }

    public class AuthenticationService
    {
        private readonly ConcurrentDictionary<string, AuthAttemptRecord> _attemptTracker;
        private readonly ICredentialStore _credentialStore;
        private readonly FeatureFlags _flags;
        private readonly SemaphoreSlim _cleanupLock = new SemaphoreSlim(1, 1);

        public AuthenticationService(ICredentialStore credentialStore, FeatureFlags flags)
        {
            _attemptTracker = new ConcurrentDictionary<string, AuthAttemptRecord>();
            _credentialStore = credentialStore;
            _flags = flags;
        }

        public async Task<AuthResult> AuthenticateNodeAsync(string nodeId, string apiKey, string sourceIp)
        {
            var trackingKey = BuildTrackingKey(nodeId, sourceIp);
            var record = _attemptTracker.GetOrAdd(trackingKey, _ => new AuthAttemptRecord());

            if (_flags.EnableAccountLockout && IsLockedOut(record))
            {
                return AuthResult.LockedOut(record.LockedUntil.Value);
            }

            if (_flags.EnableRateLimiting && IsRateLimited(record, sourceIp))
            {
                return AuthResult.RateLimited();
            }

            if (_flags.EnableProgressiveDelay)
            {
                await ApplyProgressiveDelay(record);
            }

            var isValid = await _credentialStore.ValidateApiKeyAsync(nodeId, apiKey);

            UpdateAttemptRecord(record, isValid, trackingKey);

            if (isValid)
            {
                return AuthResult.Success(GenerateSessionToken(nodeId));
            }

            return AuthResult.InvalidCredentials(record.FailedCount, _flags.MaxFailedAttempts);
        }

        private string BuildTrackingKey(string nodeId, string sourceIp)
        {
            // Track by nodeId alone when rate limiting is disabled,
            // track by composite key when enabled
            if (_flags.EnableRateLimiting)
            {
                return $"{nodeId}:{sourceIp}";
            }
            return nodeId;
        }

        private bool IsLockedOut(AuthAttemptRecord record)
        {
            if (record.LockedUntil == null) return false;
            if (DateTime.UtcNow >= record.LockedUntil.Value)
            {
                // Lockout expired - reset
                record.LockedUntil = null;
                record.FailedCount = 0;
                return false;
            }
            return true;
        }

        private bool IsRateLimited(AuthAttemptRecord record, string sourceIp)
        {
            var now = DateTime.UtcNow;
            var window = TimeSpan.FromSeconds(_flags.RateLimitWindowSeconds);

            // Prune old timestamps
            while (record.RequestTimestamps.Count > 0 &&
                   now - record.RequestTimestamps.Peek() > window)
            {
                record.RequestTimestamps.Dequeue();
            }

            record.RequestTimestamps.Enqueue(now);
            return record.RequestTimestamps.Count > _flags.MaxRequestsPerWindow;
        }

        private async Task ApplyProgressiveDelay(AuthAttemptRecord record)
        {
            if (record.FailedCount > 0)
            {
                var delayMs = Math.Min(record.FailedCount * 1000, 10000);
                await Task.Delay(delayMs);
            }
        }

        private void UpdateAttemptRecord(AuthAttemptRecord record, bool success, string trackingKey)
        {
            if (success)
            {
                record.FailedCount = 0;
                record.LockedUntil = null;
                return;
            }

            record.FailedCount++;
            record.LastAttempt = DateTime.UtcNow;

            if (_flags.EnableAccountLockout && record.FailedCount >= _flags.MaxFailedAttempts)
            {
                record.LockedUntil = DateTime.UtcNow.AddSeconds(_flags.LockoutDurationSeconds);
            }
        }

        private string GenerateSessionToken(string nodeId)
        {
            var tokenBytes = new byte[32];
            using (var rng = RandomNumberGenerator.Create())
            {
                rng.GetBytes(tokenBytes);
            }
            return Convert.ToBase64String(tokenBytes);
        }

        public async Task CleanupStaleRecordsAsync()
        {
            await _cleanupLock.WaitAsync();
            try
            {
                var staleThreshold = DateTime.UtcNow.AddHours(-1);
                var keysToRemove = new List<string>();

                foreach (var kvp in _attemptTracker)
                {
                    if (kvp.Value.LastAttempt < staleThreshold && kvp.Value.LockedUntil == null)
                    {
                        keysToRemove.Add(kvp.Key);
                    }
                }

                foreach (var key in keysToRemove)
                {
                    _attemptTracker.TryRemove(key, out _);
                }
            }
            finally
            {
                _cleanupLock.Release();
            }
        }
    }

    public class AuthResult
    {
        public bool IsSuccess { get; private set; }
        public string Token { get; private set; }
        public string ErrorReason { get; private set; }
        public int AttemptsRemaining { get; private set; }
        public DateTime? RetryAfter { get; private set; }

        public static AuthResult Success(string token) => new AuthResult { IsSuccess = true, Token = token };
        public static AuthResult LockedOut(DateTime until) => new AuthResult { ErrorReason = "AccountLocked", RetryAfter = until };
        public static AuthResult RateLimited() => new AuthResult { ErrorReason = "RateLimited" };
        public static AuthResult InvalidCredentials(int failed, int max) => new AuthResult { ErrorReason = "InvalidCredentials", AttemptsRemaining = max - failed };
    }

    public interface ICredentialStore
    {
        Task<bool> ValidateApiKeyAsync(string nodeId, string apiKey);
    }
}
